from typing import Annotated
from fastapi import Depends, HTTPException

ROLE_PERMS = {"viewer": {"reports:read"}, "admin": {"reports:read", "reports:delete"}}

def current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> User:
    claims = verify_access_token(token)      # signature, exp, aud, iss
    return User(id=int(claims["sub"]), org_id=claims["org_id"], role=claims["role"])

def require(perm: str):
    def checker(user: Annotated[User, Depends(current_user)]) -> User:
        if perm not in ROLE_PERMS.get(user.role, set()):
            raise HTTPException(403, "forbidden")
        return user
    return checker

@app.delete("/reports/{report_id}")
def delete_report(report_id: int, user: Annotated[User, Depends(require("reports:delete"))], conn: Conn):
    with conn.cursor() as cur:               # org_id from the token, never from the request
        cur.execute("DELETE FROM reports WHERE id = %s AND org_id = %s RETURNING id",
                    (report_id, user.org_id))
        if cur.fetchone() is None:
            raise HTTPException(404, "report not found")   # don't reveal other tenants' data
